   1→import { useState, useCallback } from 'react';
   2→import { useFolderStore } from '../stores/folder.store';
   3→import { useVaultStore } from '../stores/vault.store';
   4→import { useAuthStore } from '../stores/auth.store';
   5→import { unpinFromIpfs } from '../lib/api/ipfs';
   6→import { useQuotaStore } from '../stores/quota.store';
   7→import * as folderService from '../services/folder.service';
   8→import { reWrapForRecipients } from '../services/share.service';
   9→import {
  10→  createFileMetadata,
  11→  resolveFileMetadata,
  12→  updateFileMetadata,
  13→  shouldCreateVersion,
  14→  restoreVersion,
  15→  deleteVersion,
  16→  getFileIpnsPrivateKey,
  17→} from '../services/file-metadata.service';
  18→import type { FileIpnsRecordPayload } from '../services/file-metadata.service';
  19→import type { FolderNode } from '../stores/folder.store';
  20→import type { FolderEntry, FilePointer, FolderChild } from '@cipherbox/crypto';
  21→import { unwrapKey, hexToBytes } from '@cipherbox/crypto';
  22→
  23→/** Maximum folder nesting depth per FOLD-03 */
  24→const MAX_FOLDER_DEPTH = 20;
  25→
  26→/**
  27→ * State for folder operations.
  28→ */
  29→type FolderOperationState = {
  30→  isLoading: boolean;
  31→  error: string | null;
  32→};
  33→
  34→/**
  35→ * Get the root folder state from vault and folder stores.
  36→ * Root folder uses vault keys directly.
  37→ */
  38→function getRootFolderState(
  39→  vaultStore: ReturnType<typeof useVaultStore.getState>,
  40→  folders: Record<string, FolderNode>
  41→): FolderNode | null {
  42→  if (!vaultStore.rootFolderKey || !vaultStore.rootIpnsKeypair || !vaultStore.rootIpnsName) {
  43→    return null;
  44→  }
  45→
  46→  // If we have an explicit root folder in the tree, use it
  47→  const existingRoot = folders['root'];
  48→  if (existingRoot) return existingRoot;
  49→
  50→  // Otherwise construct from vault state
  51→  return {
  52→    id: 'root',
  53→    name: 'My Vault',
  54→    ipnsName: vaultStore.rootIpnsName,
  55→    parentId: null,
  56→    children: [],
  57→    isLoaded: false,
  58→    isLoading: false,
  59→    sequenceNumber: 0n,
  60→    folderKey: vaultStore.rootFolderKey,
  61→    ipnsPrivateKey: vaultStore.rootIpnsKeypair.privateKey,
  62→  };
  63→}
  64→
  65→/**
  66→ * Calculate folder depth by walking up the tree.
  67→ */
  68→function calculateFolderDepth(folderId: string, folders: Record<string, FolderNode>): number {
  69→  return folderService.getDepth(folderId, folders);
  70→}
  71→
  72→/**
  73→ * React hook for folder operations with loading/error state.
  74→ *
  75→ * Provides createFolder, renameItem, moveItem, and deleteItem operations
  76→ * that wrap folder.service functions with proper state management.
  77→ *
  78→ * @example
  79→ * ```tsx
  80→ * function FolderActions() {
  81→ *   const { isLoading, error, createFolder, deleteItem } = useFolder();
  82→ *
  83→ *   const handleCreate = async () => {
  84→ *     try {
  85→ *       await createFolder('New Folder', currentFolderId);
  86→ *     } catch (err) {
  87→ *       // Error also in error state
  88→ *     }
  89→ *   };
  90→ *
  91→ *   return (
  92→ *     <div>
  93→ *       {isLoading && <Spinner />}
  94→ *       {error && <ErrorMessage>{error}</ErrorMessage>}
  95→ *       <button onClick={handleCreate}>New Folder</button>
  96→ *     </div>
  97→ *   );
  98→ * }
  99→ * ```
 100→ */
 101→export function useFolder() {
 102→  const [state, setState] = useState<FolderOperationState>({
 103→    isLoading: false,
 104→    error: null,
 105→  });
 106→
 107→  // Get folder store for reactive updates
 108→  // Note: We use getState() in callbacks to avoid stale closures
 109→  const folderStore = useFolderStore();
 110→
 111→  /**
 112→   * Create a new folder.
 113→   *
 114→   * @param name - Folder name
 115→   * @param parentId - Parent folder ID (null for root, or folder UUID)
 116→   * @returns Created folder entry
 117→   * @throws Error if depth limit exceeded or creation fails
 118→   */
 119→  const handleCreate = useCallback(
 120→    async (name: string, parentId: string | null): Promise<FolderEntry> => {
 121→      setState({ isLoading: true, error: null });
 122→      try {
 123→        const folders = useFolderStore.getState().folders;
 124→        const vault = useVaultStore.getState();
 125→        const auth = useAuthStore.getState();
 126→
 127→        // Validate depth limit before creating (FOLD-03)
 128→        const parentDepth = folderService.getDepth(parentId, folders);
 129→        if (parentDepth >= MAX_FOLDER_DEPTH) {
 130→          throw new Error(`Cannot create folder: maximum depth of ${MAX_FOLDER_DEPTH} exceeded`);
 131→        }
 132→
 133→        // Get user's ECIES keypair for vault cryptographic operations (public + private keys stored in memory after login)
 134→        // The public key is used here for key wrapping; the private key remains client-side for decryption operations.
 135→        if (!auth.vaultKeypair) {
 136→          throw new Error('No ECIES keypair available - please log in again');
 137→        }
 138→        const userPublicKey = auth.vaultKeypair.publicKey;
 139→
 140→        // Create the folder (generates keys, wraps with user public key, TEE-encrypts IPNS key)
 141→        const { folder, ipnsPrivateKey, folderKey, encryptedIpnsPrivateKey, keyEpoch } =
 142→          await folderService.createFolder({
 143→            parentFolderId: parentId,
 144→            name,
 145→            userPublicKey,
 146→            folders,
 147→          });
 148→
 149→        // Get parent folder state
 150→        const parentFolder =
 151→          parentId && folders[parentId] ? folders[parentId] : getRootFolderState(vault, folders);
 152→
 153→        if (!parentFolder) {
 154→          throw new Error('Parent folder not found or vault not initialized');
 155→        }
 156→
 157→        // Add to parent's children
 158→        const newChildren = [...parentFolder.children, folder];
 159→
 160→        // Update parent folder metadata and publish IPNS
 161→        await folderService.updateFolderMetadata({
 162→          folderId: parentFolder.id,
 163→          children: newChildren,
 164→          folderKey: parentFolder.folderKey,
 165→          ipnsPrivateKey: parentFolder.ipnsPrivateKey,
 166→          ipnsName: parentFolder.ipnsName,
 167→          sequenceNumber: parentFolder.sequenceNumber,
 168→        });
 169→
 170→        // First publish for the new folder's own IPNS record with TEE-encrypted key
 171→        // This sends encryptedIpnsPrivateKey to backend for TEE republish enrollment
 172→        await folderService.updateFolderMetadata({
 173→          folderId: folder.id,
 174→          children: [],
 175→          folderKey,
 176→          ipnsPrivateKey,
 177→          ipnsName: folder.ipnsName,
 178→          sequenceNumber: 0n,
 179→          encryptedIpnsPrivateKey,
 180→          keyEpoch,
 181→        });
 182→
 183→        // Update local state - add new folder to tree
 184→        useFolderStore.getState().updateFolderChildren(parentFolder.id, newChildren);
 185→
 186→        // Also add the new folder node to the store (with its decrypted keys)
 187→        const newFolderNode: FolderNode = {
 188→          id: folder.id,
 189→          name: folder.name,
 190→          ipnsName: folder.ipnsName,
 191→          parentId: parentFolder.id,
 192→          children: [],
 193→          isLoaded: true,
 194→          isLoading: false,
 195→          sequenceNumber: 0n,
 196→          folderKey,
 197→          ipnsPrivateKey,
 198→        };
 199→        useFolderStore.getState().setFolder(newFolderNode);
 200→
 201→        // Post-create: re-wrap new subfolder key for share recipients (fire-and-forget)
 202→        reWrapForRecipients({
 203→          folderIpnsName: parentFolder.ipnsName,
 204→          folders: useFolderStore.getState().folders,
 205→          currentFolderId: parentFolder.id,
 206→          newItems: [{ keyType: 'folder', itemId: folder.id, plaintextKey: folderKey }],
 207→        }).catch((err) => {
 208→          console.warn('[share] Post-create subfolder re-wrapping failed:', err);
 209→        });
 210→
 211→        setState({ isLoading: false, error: null });
 212→        return folder;
 213→      } catch (err) {
 214→        const error = err instanceof Error ? err.message : 'Failed to create folder';
 215→        setState({ isLoading: false, error });
 216→        throw err;
 217→      }
 218→    },
 219→    []
 220→  );
 221→
 222→  /**
 223→   * Rename a file or folder.
 224→   *
 225→   * @param itemId - ID of item to rename
 226→   * @param itemType - 'file' or 'folder'
 227→   * @param newName - New name
 228→   * @param parentId - Parent folder ID
 229→   */
 230→  const handleRename = useCallback(
 231→    async (
 232→      itemId: string,
 233→      itemType: 'file' | 'folder',
 234→      newName: string,
 235→      parentId: string
 236→    ): Promise<void> => {
 237→      setState({ isLoading: true, error: null });
 238→      try {
 239→        const folders = useFolderStore.getState().folders;
 240→        const vault = useVaultStore.getState();
 241→
 242→        // Get parent folder state
 243→        const parentFolder =
 244→          parentId === 'root' ? getRootFolderState(vault, folders) : folders[parentId];
 245→
 246→        if (!parentFolder) throw new Error('Parent folder not found');
 247→
 248→        if (itemType === 'folder') {
 249→          await folderService.renameFolder({
 250→            folderId: itemId,
 251→            newName,
 252→            parentFolderState: parentFolder,
 253→          });
 254→
 255→          // Update local folder state name
 256→          useFolderStore.getState().updateFolderName(itemId, newName);
 257→        } else {
 258→          await folderService.renameFile({
 259→            fileId: itemId,
 260→            newName,
 261→            parentFolderState: parentFolder,
 262→          });
 263→        }
 264→
 265→        // Update parent's children with new name
 266→        const updatedChildren = parentFolder.children.map((child) => {
 267→          if (child.id === itemId) {
 268→            return { ...child, name: newName, modifiedAt: Date.now() };
 269→          }
 270→          return child;
 271→        });
 272→        useFolderStore.getState().updateFolderChildren(parentId, updatedChildren);
 273→
 274→        setState({ isLoading: false, error: null });
 275→      } catch (err) {
 276→        const error = err instanceof Error ? err.message : 'Failed to rename';
 277→        setState({ isLoading: false, error });
 278→        throw err;
 279→      }
 280→    },
 281→    []
 282→  );
 283→
 284→  /**
 285→   * Move a file or folder to a different parent.
 286→   *
 287→   * @param itemId - ID of item to move
 288→   * @param itemType - 'file' or 'folder'
 289→   * @param sourceParentId - Current parent folder ID
 290→   * @param destParentId - Destination parent folder ID
 291→   */
 292→  const handleMove = useCallback(
 293→    async (
 294→      itemId: string,
 295→      itemType: 'file' | 'folder',
 296→      sourceParentId: string,
 297→      destParentId: string
 298→    ): Promise<void> => {
 299→      setState({ isLoading: true, error: null });
 300→      try {
 301→        const folders = useFolderStore.getState().folders;
 302→        const vault = useVaultStore.getState();
 303→
 304→        // Get source and destination folder states
 305→        const sourceFolder =
 306→          sourceParentId === 'root' ? getRootFolderState(vault, folders) : folders[sourceParentId];
 307→
 308→        const destFolder =
 309→          destParentId === 'root' ? getRootFolderState(vault, folders) : folders[destParentId];
 310→
 311→        if (!sourceFolder || !destFolder) {
 312→          throw new Error('Source or destination folder not found');
 313→        }
 314→
 315→        if (itemType === 'folder') {
 316→          await folderService.moveFolder({
 317→            folderId: itemId,
 318→            sourceFolderState: sourceFolder,
 319→            destFolderState: destFolder,
 320→            folders,
 321→          });
 322→
 323→          // Update the moved folder's parentId in local state
 324→          const movedFolder = folders[itemId];
 325→          if (movedFolder) {
 326→            useFolderStore.getState().setFolder({
 327→              ...movedFolder,
 328→              parentId: destParentId,
 329→            });
 330→          }
 331→        } else {
 332→          await folderService.moveFile({
 333→            fileId: itemId,
 334→            sourceFolderState: sourceFolder,
 335→            destFolderState: destFolder,
 336→          });
 337→        }
 338→
 339→        // Update source folder's children (remove item)
 340→        const updatedSourceChildren = sourceFolder.children.filter((c) => c.id !== itemId);
 341→        useFolderStore.getState().updateFolderChildren(sourceParentId, updatedSourceChildren);
 342→
 343→        // Update dest folder's children (add item)
 344→        const movedItem = sourceFolder.children.find((c) => c.id === itemId);
 345→        if (movedItem) {
 346→          const updatedDestChildren = [
 347→            ...destFolder.children,
 348→            { ...movedItem, modifiedAt: Date.now() },
 349→          ];
 350→          useFolderStore.getState().updateFolderChildren(destParentId, updatedDestChildren);
 351→        }
 352→
 353→        setState({ isLoading: false, error: null });
 354→      } catch (err) {
 355→        const error = err instanceof Error ? err.message : 'Failed to move';
 356→        setState({ isLoading: false, error });
 357→        throw err;
 358→      }
 359→    },
 360→    []
 361→  );
 362→
 363→  /**
 364→   * Move multiple files/folders to a destination in a single batch.
 365→   *
 366→   * Uses add-before-remove pattern. Publishes IPNS once for the destination
 367→   * and once for the source (2 total), regardless of how many items are moved.
 368→   *
 369→   * @param items - Array of { id, type } to move
 370→   * @param sourceParentId - Current parent folder ID (all items must share the same parent)
 371→   * @param destParentId - Destination parent folder ID
 372→   */
 373→  const handleMoveItems = useCallback(
 374→    async (
 375→      items: Array<{ id: string; type: 'file' | 'folder' }>,
 376→      sourceParentId: string,
 377→      destParentId: string
 378→    ): Promise<void> => {
 379→      setState({ isLoading: true, error: null });
 380→      try {
 381→        const folders = useFolderStore.getState().folders;
 382→        const vault = useVaultStore.getState();
 383→
 384→        const sourceFolder =
 385→          sourceParentId === 'root' ? getRootFolderState(vault, folders) : folders[sourceParentId];
 386→        const destFolder =
 387→          destParentId === 'root' ? getRootFolderState(vault, folders) : folders[destParentId];
 388→
 389→        if (!sourceFolder || !destFolder) {
 390→          throw new Error('Source or destination folder not found');
 391→        }
 392→
 393→        const itemIds = new Set(items.map((i) => i.id));
 394→        const movedChildren = sourceFolder.children.filter((c) => itemIds.has(c.id));
 395→        const now = Date.now();
 396→
 397→        // Validate all items
 398→        const batchNames = new Set<string>();
 399→        for (const child of movedChildren) {
 400→          // Intra-batch duplicate name check
 401→          if (batchNames.has(child.name)) {
 402→            throw new Error(`Multiple selected items share the name "${child.name}"`);
 403→          }
 404→          batchNames.add(child.name);
 405→
 406→          // Name collision check against destination
 407→          const nameExists = destFolder.children.some((c) => c.name === child.name);
 408→          if (nameExists) {
 409→            throw new Error(`An item named "${child.name}" already exists in the destination`);
 410→          }
 411→
 412→          if (child.type === 'folder') {
 413→            // Prevent moving folder into itself or descendant
 414→            if (folderService.isDescendantOf(destFolder.id, child.id, folders)) {
 415→              throw new Error(`Cannot move "${child.name}" into itself or its subfolder`);
 416→            }
 417→
 418→            // Depth limit check
 419→            const destDepth = folderService.getDepth(destFolder.id, folders);
 420→            const subtreeDepth = folderService.calculateSubtreeDepth(child.id, folders);
 421→            if (destDepth + 1 + subtreeDepth > MAX_FOLDER_DEPTH) {
 422→              throw new Error(
 423→                `Cannot move "${child.name}": would exceed maximum folder depth of ${MAX_FOLDER_DEPTH}`
 424→              );
 425→            }
 426→          }
 427→        }
 428→
 429→        // ADD all to destination FIRST (add-before-remove pattern)
 430→        const destChildren = [
 431→          ...destFolder.children,
 432→          ...movedChildren.map((c) => ({ ...c, modifiedAt: now })),
 433→        ];
 434→
 435→        const { newSequenceNumber: destSeq } = await folderService.updateFolderMetadata({
 436→          folderId: destFolder.id,
 437→          children: destChildren,
 438→          folderKey: destFolder.folderKey,
 439→          ipnsPrivateKey: destFolder.ipnsPrivateKey,
 440→          ipnsName: destFolder.ipnsName,
 441→          sequenceNumber: destFolder.sequenceNumber,
 442→        });
 443→
 444→        // REMOVE all from source AFTER destination confirmed
 445→        const sourceChildren = sourceFolder.children.filter((c) => !itemIds.has(c.id));
 446→
 447→        const { newSequenceNumber: sourceSeq } = await folderService.updateFolderMetadata({
 448→          folderId: sourceFolder.id,
 449→          children: sourceChildren,
 450→          folderKey: sourceFolder.folderKey,
 451→          ipnsPrivateKey: sourceFolder.ipnsPrivateKey,
 452→          ipnsName: sourceFolder.ipnsName,
 453→          // Re-read sequence in case source === dest parent was updated above
 454→          sequenceNumber: sourceFolder.id === destFolder.id ? destSeq : sourceFolder.sequenceNumber,
 455→        });
 456→
 457→        // Update local state
 458→        const store = useFolderStore.getState();
 459→        store.updateFolderChildren(sourceParentId, sourceChildren);
 460→        store.updateFolderChildren(destParentId, destChildren);
 461→        store.updateFolderSequence(destParentId, destSeq);
 462→        store.updateFolderSequence(sourceParentId, sourceSeq);
 463→
 464→        for (const item of items) {
 465→          if (item.type === 'folder') {
 466→            const movedFolder = folders[item.id];
 467→            if (movedFolder) {
 468→              store.setFolder({ ...movedFolder, parentId: destParentId });
 469→            }
 470→          }
 471→        }
 472→
 473→        setState({ isLoading: false, error: null });
 474→      } catch (err) {
 475→        const error = err instanceof Error ? err.message : 'Failed to move items';
 476→        setState({ isLoading: false, error });
 477→        throw err;
 478→      }
 479→    },
 480→    []
 481→  );
 482→
 483→  /**
 484→   * Delete a file or folder.
 485→   *
 486→   * @param itemId - ID of item to delete
 487→   * @param itemType - 'file' or 'folder'
 488→   * @param parentId - Parent folder ID
 489→   */
 490→  const handleDelete = useCallback(
 491→    async (itemId: string, itemType: 'file' | 'folder', parentId: string): Promise<void> => {
 492→      setState({ isLoading: true, error: null });
 493→      try {
 494→        const folders = useFolderStore.getState().folders;
 495→        const vault = useVaultStore.getState();
 496→
 497→        // Get parent folder state
 498→        const parentFolder =
 499→          parentId === 'root' ? getRootFolderState(vault, folders) : folders[parentId];
 500→
 501→        if (!parentFolder) throw new Error('Parent folder not found');
 502→
 503→        if (itemType === 'folder') {
 504→          await folderService.deleteFolder({
 505→            folderId: itemId,
 506→            parentFolderState: parentFolder,
 507→            getFolderState: (id) => folders[id],
 508→            unpinCid: unpinFromIpfs,
 509→          });
 510→
 511→          // Remove folder from local state
 512→          useFolderStore.getState().removeFolder(itemId);
 513→        } else {
 514→          await folderService.deleteFileFromFolder({
 515→            fileId: itemId,
 516→            parentFolderState: parentFolder,
 517→          });
 518→        }
 519→
 520→        // Update parent's children (remove item)
 521→        const updatedChildren = parentFolder.children.filter((c) => c.id !== itemId);
 522→        useFolderStore.getState().updateFolderChildren(parentId, updatedChildren);
 523→
 524→        setState({ isLoading: false, error: null });
 525→      } catch (err) {
 526→        const error = err instanceof Error ? err.message : 'Failed to delete';
 527→        setState({ isLoading: false, error });
 528→        throw err;
 529→      }
 530→    },
 531→    []
 532→  );
 533→
 534→  /**
 535→   * Delete multiple files/folders in a single IPNS publish.
 536→   *
 537→   * Removes all items from parent's children array, collects CIDs to unpin,
 538→   * then publishes metadata and IPNS once for the entire batch.
 539→   *
 540→   * @param items - Array of { id, type } to delete
 541→   * @param parentId - Parent folder ID (all items must share the same parent)
 542→   */
 543→  const handleDeleteItems = useCallback(
 544→    async (
 545→      items: Array<{ id: string; type: 'file' | 'folder' }>,
 546→      parentId: string
 547→    ): Promise<void> => {
 548→      setState({ isLoading: true, error: null });
 549→      try {
 550→        const folders = useFolderStore.getState().folders;
 551→        const vault = useVaultStore.getState();
 552→
 553→        const parentFolder =
 554→          parentId === 'root' ? getRootFolderState(vault, folders) : folders[parentId];
 555→
 556→        if (!parentFolder) throw new Error('Parent folder not found');
 557→
 558→        const itemIds = new Set(items.map((i) => i.id));
 559→
 560→        // Collect nested folder IDs to remove from store
 561→        // In v2, file children are FilePointers (no inline CID). File IPNS/TEE
 562→        // enrollments will expire naturally (24h IPNS lifetime). Phase 14 adds cleanup.
 563→        const folderIdsToRemove: string[] = [];
 564→
 565→        const collectFolderIds = (folderId: string) => {
 566→          folderIdsToRemove.push(folderId);
 567→          const folder = folders[folderId];
 568→          if (!folder) return;
 569→          for (const child of folder.children) {
 570→            if (child.type === 'folder') {
 571→              collectFolderIds(child.id);
 572→            }
 573→          }
 574→        };
 575→
 576→        for (const item of items) {
 577→          if (item.type === 'folder') {
 578→            collectFolderIds(item.id);
 579→          }
 580→        }
 581→
 582→        // Remove all items from parent's children in one pass
 583→        const updatedChildren = parentFolder.children.filter((c) => !itemIds.has(c.id));
 584→
 585→        // Single IPNS publish for the entire batch
 586→        await folderService.updateFolderMetadata({
 587→          folderId: parentFolder.id,
 588→          children: updatedChildren,
 589→          folderKey: parentFolder.folderKey,
 590→          ipnsPrivateKey: parentFolder.ipnsPrivateKey,
 591→          ipnsName: parentFolder.ipnsName,
 592→          sequenceNumber: parentFolder.sequenceNumber,
 593→        });
 594→
 595→        // Update local state — remove all nested folders from store
 596→        const store = useFolderStore.getState();
 597→        store.updateFolderChildren(parentId, updatedChildren);
 598→        for (const folderId of folderIdsToRemove) {
 599→          store.removeFolder(folderId);
 600→        }
 601→
 602→        setState({ isLoading: false, error: null });
 603→      } catch (err) {
 604→        const error = err instanceof Error ? err.message : 'Failed to delete items';
 605→        setState({ isLoading: false, error });
 606→        throw err;
 607→      }
 608→    },
 609→    []
 610→  );
 611→
 612→  /**
 613→   * Add a file to a folder after upload (v2).
 614→   *
 615→   * Creates per-file IPNS metadata, then registers FilePointer in folder.
 616→   *
 617→   * @param parentId - Parent folder ID ('root' or folder UUID)
 618→   * @param fileData - Uploaded file data from upload service
 619→   * @returns Created file pointer
 620→   */
 621→  const handleAddFile = useCallback(
 622→    async (
 623→      parentId: string,
 624→      fileData: {
 625→        cid: string;
 626→        wrappedKey: string;
 627→        iv: string;
 628→        originalName: string;
 629→        originalSize: number;
 630→        mimeType?: string;
 631→        encryptionMode?: 'GCM' | 'CTR';
 632→      }
 633→    ): Promise<FilePointer> => {
 634→      setState({ isLoading: true, error: null });
 635→      try {
 636→        const folders = useFolderStore.getState().folders;
 637→        const vault = useVaultStore.getState();
 638→        const auth = useAuthStore.getState();
 639→
 640→        if (!auth.vaultKeypair) {
 641→          throw new Error('No ECIES keypair available - please log in again');
 642→        }
 643→
 644→        // Get parent folder state
 645→        const parentFolder =
 646→          parentId === 'root' ? getRootFolderState(vault, folders) : folders[parentId];
 647→
 648→        if (!parentFolder) {
 649→          throw new Error('Parent folder not found or vault not initialized');
 650→        }
 651→
 652→        // 1. Generate fileId and create per-file IPNS metadata
 653→        const fileId = crypto.randomUUID();
 654→        const { ipnsRecord, ipnsPrivateKeyEncrypted } = await createFileMetadata({
