 665→
 666→        // 2. Register FilePointer in folder (batch publishes file + folder IPNS)
 667→        const { filePointer, newSequenceNumber } = await folderService.addFileToFolder({
 668→          parentFolderState: parentFolder,
 669→          fileId,
 670→          name: fileData.originalName,
 671→          fileIpnsRecord: ipnsRecord,
 672→          ipnsPrivateKeyEncrypted,
 673→        });
 674→
 675→        // 3. Update local state with new child and sequence number
 676→        const updatedChildren: FolderChild[] = [...parentFolder.children, filePointer];
