 678→        store.updateFolderChildren(parentId, updatedChildren);
 679→        store.updateFolderSequence(parentId, newSequenceNumber);
 680→
 681→        // 4. Post-upload: re-wrap file key for share recipients (fire-and-forget)
 682→        // Unwrap the fileKey from the owner-wrapped key, then delegate to reWrapForRecipients
 683→        (async () => {
 684→          try {
 685→            const authState = useAuthStore.getState();
 686→            if (!authState.vaultKeypair) return;
 687→            const fileKey = await unwrapKey(
 688→              hexToBytes(fileData.wrappedKey),
 689→              authState.vaultKeypair.privateKey
 690→            );
 691→            try {
 692→              await reWrapForRecipients({
 693→                folderIpnsName: parentFolder.ipnsName,
 694→                folders: useFolderStore.getState().folders,
 695→                currentFolderId: parentFolder.id,
 696→                newItems: [{ keyType: 'file', itemId: fileId, plaintextKey: fileKey }],
 697→              });
 698→            } finally {
 699→              fileKey.fill(0);
 700→            }
 701→          } catch (err) {
 702→            console.warn('[share] Post-upload file re-wrapping failed:', err);
 703→          }
 704→        })();
 705→
 706→        setState({ isLoading: false, error: null });
 707→        return filePointer;
 708→      } catch (err) {
 709→        const error = err instanceof Error ? err.message : 'Failed to add file';
 710→        setState({ isLoading: false, error });
 711→        throw err;
 712→      }
 713→    },
 714→    []
 715→  );
