 717→  /**
 718→   * Add multiple files to a folder after upload (v2 batch).
 719→   *
 720→   * Creates per-file IPNS metadata for each file, then registers all
 721→   * FilePointers via a single batch IPNS publish.
 722→   *
 723→   * @param parentId - Parent folder ID ('root' or folder UUID)
 724→   * @param filesData - Array of uploaded file data from upload service
 725→   * @returns Created file pointers
 726→   */
 727→  const handleAddFiles = useCallback(
 728→    async (
 729→      parentId: string,
 730→      filesData: Array<{
 731→        cid: string;
 732→        wrappedKey: string;
 733→        iv: string;
 734→        originalName: string;
 735→        originalSize: number;
 736→        mimeType?: string;
 737→        encryptionMode?: 'GCM' | 'CTR';
 738→      }>
 739→    ): Promise<FilePointer[]> => {
 740→      setState({ isLoading: true, error: null });
 741→      try {
 742→        const folders = useFolderStore.getState().folders;
 743→        const vault = useVaultStore.getState();
 744→        const auth = useAuthStore.getState();
 745→
 746→        if (!auth.vaultKeypair) {
 747→          throw new Error('No ECIES keypair available - please log in again');
 748→        }
 749→
 750→        // Get parent folder state
 751→        const parentFolder =
 752→          parentId === 'root' ? getRootFolderState(vault, folders) : folders[parentId];
 753→
 754→        if (!parentFolder) {
 755→          throw new Error('Parent folder not found or vault not initialized');
 756→        }
 757→
 758→        // 1. Create per-file IPNS metadata for each file
 759→        const userPublicKey = auth.vaultKeypair.publicKey;
 760→        const filesWithRecords = await Promise.all(
 761→          filesData.map(async (f) => {
 762→            const fileId = crypto.randomUUID();
 763→            const { ipnsRecord, ipnsPrivateKeyEncrypted } = await createFileMetadata({
 764→              fileId,
 765→              cid: f.cid,
 766→              fileKeyEncrypted: f.wrappedKey,
 767→              fileIv: f.iv,
 768→              size: f.originalSize,
 769→              mimeType: f.mimeType ?? 'application/octet-stream',
 770→              folderKey: parentFolder.folderKey,
 771→              userPublicKey,
 772→              encryptionMode: f.encryptionMode,
 773→            });
 774→            return {
 775→              fileId,
 776→              name: f.originalName,
 777→              fileIpnsRecord: ipnsRecord,
 778→              ipnsPrivateKeyEncrypted,
 779→            };
 780→          })
 781→        );
 782→
 783→        // 2. Register FilePointers in folder (batch publishes all IPNS records)
 784→        const { filePointers, newSequenceNumber } = await folderService.addFilesToFolder({
 785→          parentFolderState: parentFolder,
 786→          files: filesWithRecords,
 787→        });
 788→
 789→        // 3. Update local state with new children and sequence number
 790→        const store = useFolderStore.getState();
 791→        store.updateFolderChildren(parentId, [...parentFolder.children, ...filePointers]);
 792→        store.updateFolderSequence(parentId, newSequenceNumber);
 793→
 794→        // 4. Post-upload: re-wrap file keys for share recipients (fire-and-forget)
 795→        (async () => {
 796→          const newItems: Array<{
 797→            keyType: 'file' | 'folder';
 798→            itemId: string;
 799→            plaintextKey: Uint8Array;
 800→          }> = [];
 801→          try {
 802→            const authState = useAuthStore.getState();
 803→            if (!authState.vaultKeypair) return;
 804→            const privateKey = authState.vaultKeypair.privateKey;
 805→            for (let i = 0; i < filesData.length; i++) {
 806→              const fileKey = await unwrapKey(hexToBytes(filesData[i].wrappedKey), privateKey);
 807→              newItems.push({
 808→                keyType: 'file',
 809→                itemId: filesWithRecords[i].fileId,
 810→                plaintextKey: fileKey,
 811→              });
 812→            }
 813→            await reWrapForRecipients({
 814→              folderIpnsName: parentFolder.ipnsName,
 815→              folders: useFolderStore.getState().folders,
 816→              currentFolderId: parentFolder.id,
 817→              newItems,
 818→            });
 819→          } catch (err) {
 820→            console.warn('[share] Post-upload batch file re-wrapping failed:', err);
 821→          } finally {
 822→            for (const item of newItems) {
 823→              item.plaintextKey.fill(0);
 824→            }
 825→          }
 826→        })();
 827→
 828→        setState({ isLoading: false, error: null });
 829→        return filePointers;
 830→      } catch (err) {
 831→        const error = err instanceof Error ? err.message : 'Failed to add files';
 832→        setState({ isLoading: false, error });
 833→        throw err;
 834→      }
 835→    },
 836→    []
