 839→  /**
 840→   * Update a file's content in-place (v2: re-encrypt, update file IPNS, folder untouched).
 841→   *
 842→   * Old CIDs are preserved as version history (VER-01). Only pruned versions
 843→   * (excess beyond max 10) have their CIDs unpinned.
 844→   *
 845→   * @param parentId - Parent folder ID ('root' or folder UUID)
 846→   * @param fileData - New file data after re-encryption
 847→   * @returns Resolves when the update is complete
 848→   */
 849→  const handleUpdateFile = useCallback(
 850→    async (
 851→      parentId: string,
 852→      fileData: {
 853→        fileId: string;
 854→        newCid: string;
 855→        newFileKeyEncrypted: string;
 856→        newFileIv: string;
 857→        newSize: number;
 858→        forceVersion?: boolean; // true for web re-upload, false/undefined for text editor
 859→      }
 860→    ): Promise<void> => {
 861→      setState({ isLoading: true, error: null });
 862→      try {
 863→        const folders = useFolderStore.getState().folders;
 864→        const vault = useVaultStore.getState();
 865→        const auth = useAuthStore.getState();
 866→
 867→        if (!auth.vaultKeypair) {
 868→          throw new Error('No ECIES keypair available - please log in again');
 869→        }
 870→
 871→        // Get parent folder state
 872→        const parentFolder =
 873→          parentId === 'root' ? getRootFolderState(vault, folders) : folders[parentId];
 874→
 875→        if (!parentFolder) {
 876→          throw new Error('Parent folder not found or vault not initialized');
 877→        }
 878→
 879→        // 1. Find the FilePointer in parent's children
 880→        const filePointer = parentFolder.children.find(
 881→          (c) => c.type === 'file' && c.id === fileData.fileId
 882→        ) as FilePointer | undefined;
 883→
 884→        if (!filePointer) {
 885→          throw new Error('File not found in folder');
 886→        }
 887→
 888→        // 2. Resolve current file metadata from IPNS
 889→        const { metadata: currentMetadata } = await resolveFileMetadata(
 890→          filePointer.fileMetaIpnsName,
 891→          parentFolder.folderKey
 892→        );
 893→
 894→        // 3. Decrypt the file IPNS private key from FilePointer (or HKDF fallback)
 895→        const { privateKey: fileIpnsPrivateKey, migratedIpnsPrivateKeyEncrypted } =
 896→          await getFileIpnsPrivateKey(
 897→            filePointer,
 898→            auth.vaultKeypair.privateKey,
 899→            auth.vaultKeypair.publicKey
 900→          );
 901→
 902→        // 4. Determine whether to create a version entry
 903→        const createVersion = shouldCreateVersion(currentMetadata, fileData.forceVersion ?? false);
 904→
 905→        let ipnsRecord: FileIpnsRecordPayload;
 906→        let prunedCids: string[];
 907→        try {
 908→          // 5. Update file metadata and publish new IPNS record
 909→          ({ ipnsRecord, prunedCids } = await updateFileMetadata({
 910→            fileIpnsPrivateKey,
 911→            fileMetaIpnsName: filePointer.fileMetaIpnsName,
 912→            folderKey: parentFolder.folderKey,
 913→            currentMetadata,
 914→            updates: {
 915→              cid: fileData.newCid,
 916→              fileKeyEncrypted: fileData.newFileKeyEncrypted,
 917→              fileIv: fileData.newFileIv,
 918→              size: fileData.newSize,
 919→            },
 920→            createVersion,
 921→          }));
 922→        } finally {
 923→          fileIpnsPrivateKey.fill(0);
 924→        }
 925→
 926→        // 6. Publish only the file IPNS record (folder metadata untouched!)
 927→        await folderService.replaceFileInFolder({
 928→          fileId: fileData.fileId,
 929→          fileIpnsRecord: ipnsRecord,
 930→          parentFolderState: parentFolder,
 931→        });
 932→
 933→        // 7. Update local state -- touch modifiedAt and persist migrated IPNS key if applicable
 934→        const updatedChildren = parentFolder.children.map((child) => {
 935→          if (child.type === 'file' && child.id === fileData.fileId) {
 936→            return {
 937→              ...child,
 938→              modifiedAt: Date.now(),
 939→              ...(migratedIpnsPrivateKeyEncrypted
 940→                ? { ipnsPrivateKeyEncrypted: migratedIpnsPrivateKeyEncrypted }
 941→                : {}),
 942→            };
 943→          }
 944→          return child;
 945→        });
 946→
 947→        const store = useFolderStore.getState();
 948→        store.updateFolderChildren(parentId, updatedChildren);
 949→
 950→        // 7b. Lazy migration: persist wrapped IPNS key to folder metadata on IPFS
 951→        if (migratedIpnsPrivateKeyEncrypted) {
 952→          folderService
 953→            .updateFolderMetadata({
 954→              folderId: parentFolder.id,
 955→              children: updatedChildren,
 956→              folderKey: parentFolder.folderKey,
 957→              ipnsPrivateKey: parentFolder.ipnsPrivateKey,
 958→              ipnsName: parentFolder.ipnsName,
 959→              sequenceNumber: parentFolder.sequenceNumber,
 960→            })
 961→            .then(({ newSequenceNumber }) => {
 962→              useFolderStore.getState().updateFolderSequence(parentId, newSequenceNumber);
 963→            })
 964→            .catch((err) => {
 965→              console.warn('Lazy IPNS key migration: folder re-publish failed, will retry:', err);
 966→            });
 967→        }
 968→
 969→        // 8. Only unpin CIDs of pruned versions (excess beyond max 10)
 970→        // Old CIDs stay pinned as version history (VER-01)
 971→        for (const prunedCid of prunedCids) {
 972→          unpinFromIpfs(prunedCid).catch(() => {});
 973→        }
 974→
 975→        // Refresh quota
 976→        useQuotaStore.getState().fetchQuota();
 977→
 978→        setState({ isLoading: false, error: null });
 979→      } catch (err) {
 980→        const error = err instanceof Error ? err.message : 'Failed to update file';
 981→        setState({ isLoading: false, error });
 982→        throw err;
 983→      }
 984→    },
 985→    []
 986→  );
