    **2. Create `apps/web/src/components/file-browser/SearchPalette.tsx`**

    Command palette overlay with terminal aesthetic. Design specs from CONTEXT.md:
    - 600px wide, centered horizontally, ~120px from top
    - 1px #00D084 border, sharp corners (0 radius)
    - Backdrop: #000000CC
    - JetBrains Mono font throughout

    Component structure:

    ```tsx
    interface SearchPaletteProps {
      isOpen: boolean;
      query: string;
      onQueryChange: (q: string) => void;
      results: SearchResult[];
      resultCount: number;
      isBuilding: boolean;
      isIndexReady: boolean;
      onClose: () => void;
      onSelectResult: (result: SearchResult) => void;
    }

    export function SearchPalette({ ... }: SearchPaletteProps) {
      const [selectedIndex, setSelectedIndex] = useState(0);
      const inputRef = useRef<HTMLInputElement>(null);
      const resultsRef = useRef<HTMLDivElement>(null);

      // Reset selection when results change
      useEffect(() => setSelectedIndex(0), [results]);

      // Focus input when opening
      useEffect(() => {
        if (isOpen) inputRef.current?.focus();
      }, [isOpen]);

      // Keyboard navigation
      const handleKeyDown = (e: React.KeyboardEvent) => {
        switch (e.key) {
          case 'ArrowDown':
            e.preventDefault();
            setSelectedIndex((i) => Math.min(i + 1, results.length - 1));
            break;
          case 'ArrowUp':
            e.preventDefault();
            setSelectedIndex((i) => Math.max(i - 1, 0));
            break;
          case 'Enter':
            e.preventDefault();
            if (results[selectedIndex]) {
              onSelectResult(results[selectedIndex]);
            }
            break;
          case 'Escape':
            e.preventDefault();
            onClose();
            break;
        }
      };

      // Scroll selected item into view
      useEffect(() => {
        const container = resultsRef.current;
        if (!container) return;
        const selected = container.children[selectedIndex] as HTMLElement | undefined;
        selected?.scrollIntoView({ block: 'nearest' });
      }, [selectedIndex]);

      // Click outside to close
      const backdropRef = useRef<HTMLDivElement>(null);
      const handleBackdropClick = (e: React.MouseEvent) => {
        if (e.target === backdropRef.current) onClose();
      };

      if (!isOpen) return null;

      // File type icon mapping (lucide icon names as Unicode or simple SVG)
      // Use simple text-based icons for terminal aesthetic:
      // folder -> [D], file -> based on extension
      // Actually use lucide-react if available, otherwise CSS-based icons

      return (
        <div
          className="search-backdrop"
          ref={backdropRef}
          onClick={handleBackdropClick}
          role="dialog"
          aria-modal="true"
          aria-label="Search files"
        >
          <div className="search-palette" onKeyDown={handleKeyDown}>
            {/* Search input */}
            <div className="search-input-row">
              <span className="search-icon">&#x2315;</span> {/* magnifying glass alternative, or use > prompt */}
              <input
                ref={inputRef}
                className="search-input"
                type="text"
                placeholder="Search files..."
                value={query}
                onChange={(e) => onQueryChange(e.target.value)}
                autoComplete="off"
                spellCheck={false}
              />
              <span className="search-esc-hint">ESC</span>
            </div>

            {/* Results area */}
            <div className="search-results" ref={resultsRef}>
              {isBuilding && (
                <div className="search-building">{'// building index...'}</div>
              )}
              {!isBuilding && isIndexReady && query.trim() && results.length === 0 && (
                <div className="search-no-results">
                  {'// no results for '}&apos;{query}&apos;
                </div>
              )}
              {results.map((result, index) => (
                <SearchResultItem
                  key={result.id}
                  result={result}
                  isSelected={index === selectedIndex}
                  onClick={() => onSelectResult(result)}
                  onMouseEnter={() => setSelectedIndex(index)}
                />
              ))}
            </div>

            {/* Footer with keyboard hints and result count */}
            <div className="search-footer">
              <span className="search-footer-hints">
                <kbd>&uarr;&darr;</kbd> navigate <kbd>&crarr;</kbd> open <kbd>esc</kbd> close
              </span>
              {results.length > 0 && (
                <span className="search-footer-count">
                  {'// '}{results.length} result{results.length !== 1 ? 's' : ''}
                </span>
              )}
            </div>
          </div>
        </div>
      );
    }
    ```

    **SearchResultItem sub-component** (in same file):

    ```tsx
    function SearchResultItem({ result, isSelected, onClick, onMouseEnter }: {
      result: SearchResult;
      isSelected: boolean;
      onClick: () => void;
      onMouseEnter: () => void;
    }) {
      // File type icon based on name extension
      const icon = getFileIcon(result.name, result.type);

      // Format date as abbreviated (e.g., "Feb 24" or "Jan 3, 2025")
      const dateStr = formatRelativeDate(result.modifiedAt);

      // Highlight matching characters in name
      const highlightedName = highlightMatches(result.name, result.match);

      return (
        <div
          className={`search-result-item ${isSelected ? 'selected' : ''}`}
          onClick={onClick}
          onMouseEnter={onMouseEnter}
          role="option"
          aria-selected={isSelected}
        >
          <span className={`search-result-icon ${isSelected ? 'icon-bright' : ''}`}>
            {icon}
          </span>
          <div className="search-result-info">
            <span className="search-result-name">{highlightedName}</span>
            <span className="search-result-path">{result.parentPath}</span>
          </div>
          <span className="search-result-date">{dateStr}</span>
        </div>
      );
    }
    ```

    **Helper functions** (in same file or a small utils section at top):

    - `getFileIcon(name, type)`: Returns a terminal-aesthetic icon character. For folders: use a folder Unicode symbol. For files: map extensions to symbols (e.g., `.pdf` -> document, `.jpg/.png` -> image, `.mp4` -> video, default -> file). Keep it simple with Unicode characters that render in JetBrains Mono. Examples: folder="D", file="F", image="I", video="V", doc="T" -- or use the bracket notation from the terminal aesthetic: `[D]`, `[F]`, etc. Actually, use simple Unicode that fits the aesthetic: folder glyph, file glyph. Check what lucide-react provides -- if it's already a dependency, use `<Folder size={16} />` and `<File size={16} />` from lucide-react. If NOT a dependency, use Unicode characters.

    - `formatRelativeDate(timestamp)`: For timestamps within the current year, show "Mon DD" (e.g., "Feb 24"). For older, show "Mon DD, YYYY". If timestamp is 0 or falsy, return empty string.

    - `highlightMatches(name, matchInfo)`: Takes the name and MiniSearch match info, returns JSX with matched characters wrapped in `<mark>` tags. MiniSearch's `match` field contains `{ fieldName: [matchedTerms] }`. For simplicity, use the `name` field matches to highlight substrings. If match info is complex, fall back to simple bold rendering of the entire name.

    **IMPORTANT CSS/a11y rules from CLAUDE.md:**
