    **Simplest integration pattern for rebuildIndex:**

    In `useSearch.ts`, also export a module-level function that FileBrowser can call:
    ```typescript
    // Module-level callback for triggering index rebuild from outside React tree
    let _rebuildCallback: (() => void) | null = null;

    export function registerRebuildCallback(cb: () => void) {
      _rebuildCallback = cb;
    }

    export function triggerSearchIndexRebuild() {
      _rebuildCallback?.();
    }
    ```

    In the useSearch hook, register the rebuild callback:
    ```typescript
    useEffect(() => {
      registerRebuildCallback(rebuildIndex);
      return () => registerRebuildCallback(() => {});
    }, [rebuildIndex]);
    ```

    This way FileBrowser just imports `triggerSearchIndexRebuild` and calls it after sync completes.

